                    *out.add(0) = *pal.add(0);
                    *out.add(1) = *pal.add(1);
                    *out.add(2) = *pal.add(2);
                    *out.add(3) = *pal.add(3);
                    out = out.add(4);
                }
                i = i.wrapping_add(1);
            }
