                    *out.add(1) = *inp.add(2);
                    *out.add(2) = *inp.add(4);
                    *out.add(3) = *inp.add(6);
                    inp = inp.add(8);
                    out = out.add(4);
                }
                i = i.wrapping_add(1);
            }
        }
    }
